import unreal,json
from pathlib import Path
instance=unreal.load_asset('/Game/LevelPrototyping/Materials/MI_Landscape_SplatMapTesting')
material=instance.get_editor_property('parent')
rows=[]
for obj in unreal.ObjectIterator(unreal.MaterialExpression):
 if obj.get_outermost()!=material.get_outermost(): continue
 if any(n in obj.get_class().get_name() for n in ['LandscapeLayer','Constant3Vector','BlendMaterialAttributes','MakeMaterialAttributes']):
  row={'name':obj.get_name(),'class':obj.get_class().get_name()}
  for p in ['layers','constant','parameter_name','layer_name','base_color','a','b','alpha','A','B','Alpha']:
   try: row[p]=str(obj.get_editor_property(p))
   except Exception: pass
  rows.append(row)
record={'material':material.get_path_name(),'nodes':rows}
Path('C:/Users/tarik/Documents/GitHub/AGP/.scratch/splatmap-v2/manual-acceptance-20261024/48-unreal-debug-layer-order.json').write_text(json.dumps(record,indent=2))
